<component name="ActionButtons.tsx">
    <modified>
        import React from 'react';
        import { Button, Tooltip, Icon } from '@chakra-ui/react';
        import { useToast } from '@chakra-ui/react';
        import { saveAs } from 'file-saver';
        import * as html2canvas from 'html2canvas';

        interface ActionButtonsProps {
            cardRef: React.RefObject<HTMLDivElement>;
            singleCardRef?: React.RefObject<HTMLDivElement>;
            flashcardCount: number;
            onExportAll?: () => void;
            onExportSingle?: () => void;
        }

        const ActionButtons: React.FC<ActionButtonsProps> = ({ cardRef, singleCardRef, flashcardCount, onExportAll, onExportSingle }) => {
            const toast = useToast();
            const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);

            const handleDownloadImage = async () => {
                if (!cardRef.current) {
                    toast({
                        title: "Error",
                        description: "Could not find the flashcard container.",
                        status: "error",
                        duration: 3000,
                        isClosable: true,
                    });
                    return;
                }

                try {
                    const canvas = await html2canvas(cardRef.current, {
                        useCORS: true,
                        scale: window.devicePixelRatio > 1 ? 1 : window.devicePixelRatio, // Adjust scale for retina
                    });
                    canvas.toBlob((blob) => {
                        if (blob) {
                            saveAs(blob, `flashcard.png`);
                            toast({
                                title: "Success",
                                description: "Flashcard image downloaded successfully.",
                                status: "success",
                                duration: 3000,
                                isClosable: true,
                            });
                        } else {
                            toast({
                                title: "Error",
                                description: "Failed to create image.",
                                status: "error",
                                duration: 3000,
                                isClosable: true,
                            });
                        }
                    }, 'image/png');
                } catch (error) {
                    console.error("Error exporting image:", error);
                    toast({
                        title: "Error",
                        description: "Failed to export flashcard as image.",
                        status: "error",
                        duration: 3000,
                        isClosable: true,
                    });
                }
            };


            return (
                <div>
                    <Tooltip label="Export this flashcard as a PDF" aria-label="Export PDF">
                        <Button colorScheme="blue" onClick={onExportSingle}>
                            <Icon boxSize={4} />
                            Export PDF
                        </Button>
                    </Tooltip>
                    <Tooltip label="Download this flashcard as an image" aria-label="Download Image">
                        <Button colorScheme="green" onClick={handleDownloadImage}>
                            <Icon boxSize={4} />
                            Download Image
                        </Button>
                    </Tooltip>
                    {flashcardCount > 1 && (
                        <Tooltip label="Export all flashcards as a single PDF" aria-label="Export All PDF">
                            <Button colorScheme="purple" onClick={onExportAll}>
                                <Icon boxSize={4} />
                                Export All PDF
                            </Button>
                        </Tooltip>
                    )}
                </div>
            );
        };

        export default ActionButtons;
    </modified>
</component>

