                                إلغاء
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* AI RESULT REVIEW SECTION */}
            {generatedResult && (
                <div className="neumorphic-outset p-6 mb-8 bg-green-50 border border-green-200 animate-fadeIn no-print">
